"""Preserve primary closure and append matched existing-source-option evidence."""
import pathlib,runpy,json,hashlib,datetime,shutil,statistics
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'outputs';SUP=OUT/'em_option_learning_v1'
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def main():
 extra=json.loads((SUP/'evaluation/summary.json').read_text());assert extra['status']=='COMPLETE_FOUR_MATCHED_NATIVE_EM_OPTION_CONTROLS';assert len(extra['records'])==4
 runpy.run_path(str(ROOT/'scripts/analyze54_v2.py'),run_name='__main__')
 archive=OUT/'primary12_only_reports_v1';assert not archive.exists();archive.mkdir()
 names=['README.md','literature_review.md','baseline_registry.md','experimental_results.md','negative_evidence.md','hypothesis_space.md','research_ideas.md','final_research_direction.md']
 for name in names:shutil.copyfile(ROOT/name,archive/name)
 table='| Task | Seed | Original False R2 | Existing True R2 | False eigenvalue error | True eigenvalue error | h10 conditional-mean error delta (True-False) |\n|---|---:|---:|---:|---:|---:|---:|\n'
 primary=json.loads((OUT/'evaluation54.json').read_text());deltas=[];edeltas=[]
 for r in extra['records']:
  original=next(x for x in primary['records'] if x['run']==r['matched_false_run']);pair=next(x for x in extra['paired'] if x['true_run']==r['run']);delta=next(h['conditional_mean_discrepancy_delta_true_minus_false'] for h in pair['horizons'] if h['h']==10);deltas.append(delta);edeltas.append(pair['eigenvalue_error_delta_true_minus_false'])
  table+=f"|{r['task']}|{r['seed']}|{original['full_smoothing_R2_train_readout']:.6f}|{r['full_smoothing_R2_train_readout']:.6f}|{original['transition_eigenvalue_mean_absolute_error']:.6g}|{r['transition_eigenvalue_mean_absolute_error']:.6g}|{delta:.6g}|\n"
 wins=sum(x<0 for x in deltas);ewins=sum(x<0 for x in edeltas)
 statement=f'The existing True option gives numerically lower h10 conditional-mean discrepancy in {wins}/4 initialization-matched pairs and lower transition-eigenvalue error in {ewins}/4. These counts describe the four fixed comparisons, without significance or independent-domain claims.'
 section='\n\n## Existing native EM option: four matched learning controls\n\n'+table+'\n'+statement+'\n\nThe original12-fit comparison is preserved in full, including its third False initialization for each task. Four additional native True runs use the same data, model, initial arrays, Adam/batch RNG, stabilization and 10,000-update terminal budget; only the already-provided posterior-gradient option changes. This is a source-option control, not a new method. All16 models and all16 diagnostic maps were frozen before the first heldout score. The extra maps were prepared first, followed by the original12-map preparation and scoring, then extra scoring.\n\nThe frozen-gradient reference dependence is configuration-specific: differentiating through the approximate E-step and taking a fixed-posterior M-step are different derivative contracts. Its presence under the public default cannot alone establish that the original paper or all existing world models lack a capability. Encoder reference dependence and proper-RPM approximation remain separate questions. A scalar gradient improvement is not automatically a forecasting or uncertainty-calibration improvement. See the complete paired horizon metrics in `outputs/em_option_learning_v1/evaluation/summary.json` and the training-only audit receipts.\n\nNo new research direction is accepted from these two synthetic tasks. If the existing option reduces a defining error, a new-primitive necessity claim is weakened. Any remaining failure must survive competent source settings and proper-likelihood controls on independent task evidence before method design. The current data do not establish broad real-domain validity or a complete probabilistic calibration result.\n'
 for name in names:
  text=(ROOT/name).read_text(encoding='utf-8')
  if name=='README.md':text='# C54 completed: 12 primary fits plus 4 existing-source-option controls\n\nThe latest report/hash receipt is `outputs/REPORT_MANIFEST54_V2.json`. The primary12-only reports are retained under `outputs/primary12_only_reports_v1/`.\n\n'+text
  (ROOT/name).write_text(text+section,encoding='utf-8')
 summary=json.loads((OUT/'summary54.json').read_text());extra_seal=json.loads((SUP/'SELECTION_SEAL54_EM_TRUE_V1.json').read_text())
 summary.update(supplemental_existing_native_em_option_fits=4,total_completed_fits=16,total_native_RP_optimizer_updates=summary['rp_optimizer_updates']+40000,matched_h10_conditional_error_improvement_count=wins,matched_eigenvalue_error_improvement_count=ewins,additional_fit_wall_seconds_sum=sum(x['runtime_seconds'] for x in extra_seal['fits']),extra_evaluation_sha256=sha(SUP/'evaluation/summary.json'),all16_models_and_readouts_frozen_before_test=extra['all_16_models_and_16_readouts_frozen_before_first_heldout_score'])
 (OUT/'summary54_with_em_option_v1.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
 manifest={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'PRIMARY12_PLUS_FOUR_EXISTING_NATIVE_EM_OPTION_CONTROLS_COMPLETE','accepted_directions':0,'overall_goal':'ACTIVE_UNACHIEVED','reports':{n:sha(ROOT/n) for n in names},'primary12_only_reports':{n:sha(archive/n) for n in names},'primary_report_manifest_preserved':sha(OUT/'REPORT_MANIFEST54_V1.json'),'summary_sha256':sha(OUT/'summary54_with_em_option_v1.json'),'extra_evaluation_sha256':sha(SUP/'evaluation/summary.json')}
 (OUT/'REPORT_MANIFEST54_V2.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8');print(json.dumps({'status':manifest['status'],'statement':statement,'accepted_directions':0}),flush=True)
if __name__=='__main__':main()
